sql_query:
SELECT "Control regimen"
FROM clinical_trials
WHERE LOWER(TRIM(COALESCE("Control regimen", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Gastric/GEJ' AND TRIM(COALESCE("Control arm", '')) = 'Chemo' AND TRIM(COALESCE("Name of ICI", '')) = 'Avelumab' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 3';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Control regimen" AS source_value FROM clinical_trials WHERE LOWER(TRIM(COALESCE("Control regimen", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Gastric/GEJ' AND TRIM(COALESCE("Control arm", '')) = 'Chemo' AND TRIM(COALESCE("Name of ICI", '')) = 'Avelumab' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 3'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_control_backbone(source_value) AS "control_backbone"
FROM base;
